async function verifiedProResponse(env,body,messages,build=false){
 const primary=selectedModel(body,env),params=modelOptions(body,env,build);
 const candidates=[{name:primary,label:'Qwen 3.8',options:{...params}}];
 // Paid-model access is never silently upgraded or retried on paid providers.
 if(!isPaidPro(body,env)){
  candidates.push({name:MODELS.glm,label:'GLM 4.7 Flash',options:{max_completion_tokens:build?2600:Math.min(params.max_completion_tokens,2400),temperature:params.temperature}});
  candidates.push({name:MODELS.gemma,label:'Gemma 4',options:{max_completion_tokens:build?2600:Math.min(params.max_completion_tokens,2100),temperature:params.temperature}});
 }
 let lastError;
 for(let i=0;i<candidates.length;i++){
  const c=candidates[i];
  try{
   const result=await env.AI.run(c.name,{messages,stream:false,...c.options});
   const answer=inferenceOutput(result);
   if(!answer)throw new Error('Empty AI content (model completed without visible text)');
   return {result,content:answer,model:c.name,label:c.label,fallback:i>0,finishReason:finishedReason(result)};
  }catch(error){
   lastError=error;
   console.warn('NOVA Pro inference attempt failed',{model:c.name,code:aiErrorCode(error)||'none',empty:/Empty AI content/.test(String(error?.message))});
   if(isQuotaProblem(error)||isPaidPro(body,env))break;
  }
 }
 throw lastError||new Error('No model produced text');
}
async function runAIWithFallback(env,body,messages,build=false){
 // Used by Build mode and non-Pro streaming. Keep model selection unchanged.
 if(body?.model==='pro')return verifiedProResponse(env,body,messages,build);
 const model=selectedModel(body,env),params=modelOptions(body,env,build);
 return {result:await env.AI.run(model,{messages,stream:!build,...params}),model,label:body.model||'Model',fallback:false};
}
// An enabled Web toggle is permission to research when useful, not a
// request to search for every greeting or spend owner search credits.
function serverSearchAppropriate(text){
 const q=String(text||'').trim().toLowerCase().replace(/\s+/g,' ').replace(/[.!?,]+$/g,'').trim();
 const explicit=/\b(?:search\s+(?:the\s+)?(?:internet|web|online)|search\s+for|look\s*up|browse\s+(?:the\s+)?web|research\b)\b/.test(q);
 if(explicit)return true;
 if(/^(?:hi|hello|hey|yo|thanks|thank you|good morning|good evening|what can you do|who are you|how (?:are|ar|r) (?:you|u|we|wi|with) (?:doing|doin|ding|going)(?: (?:today|now))?|what(?:'s| is) up|how(?:'s| is) it going|what (?:are|r) we doing)$/.test(q))return false;
 return true;
}
async function handleChat(request,env,body){
 const msgs=parseRequest(body);
 const sources=body.search&&serverSearchAppropriate(msgs.at(-1).content)?await research(msgs.at(-1).content,env):[];
 const modelMessages=prepareMessages(body,'chat',sources);
 const enc=new TextEncoder();
 if(body.model==='pro'){
  const result=await verifiedProResponse(env,body,modelMessages,false);
  const output=new ReadableStream({start(controller){
   controller.enqueue(enc.encode('event: sources\n'+'data: '+JSON.stringify({sources:sources.map(({title,url})=>({title,url}))})+'\n\n'));
   const note=result.fallback?'[NOVA Pro used '+result.label+' after another model failed]\n\n':'';
   controller.enqueue(enc.encode('data: '+JSON.stringify({response:note+result.content,finish_reason:result.finishReason})+'\n\n'));
   controller.enqueue(enc.encode('data: [DONE]\n\n'));
   controller.close();
  }});
  return new Response(output,{headers:{...commonHeaders,'Content-Type':'text/event-stream; charset=utf-8','X-Accel-Buffering':'no'}});
 }
 const chosen=await runAIWithFallback(env,body,modelMessages,false);
 const reader=chosen.result.getReader();
 const output=new ReadableStream({
  async start(controller){
   try{
    controller.enqueue(enc.encode('event: sources\n'+'data: '+JSON.stringify({sources:sources.map(({title,url})=>({title,url}))})+'\n\n'));
    while(true){const {done,value}=await reader.read();if(done)break;controller.enqueue(value)}
    controller.close();
   }catch(e){
    console.error('NOVA AI stream error',{model:chosen.model,code:aiErrorCode(e)||'unknown'});
    controller.enqueue(enc.encode('event: error\n'+'data: '+JSON.stringify({error:'The model stream stopped. Try again or select another model.'})+'\n\n'));
    controller.close();
   }
  },
  cancel(){reader.cancel().catch(()=>{})}
 });
 return new Response(output,{headers:{...commonHeaders,'Content-Type':'text/event-stream; charset=utf-8','X-Accel-Buffering':'no','Connection':'keep-alive'}});
}
// Optional AI-planned 3D geometry. Returns only a bounded, validated list of
// primitive parts; user browser builds the GLB from this safe data. Not a 3D
// generative mesh model or a replacement for Blender.
async function handle3DPlan(request,env){
 const size=Number(request.headers.get('content-length')||0);
 if(size>5000)return responseJSON({error:'3D request too large.'},413);
 let body;
 try{const raw=await request.text();if(raw.length>5000)return responseJSON({error:'3D request too large.'},413);body=JSON.parse(raw)}
 catch{return responseJSON({error:'Invalid 3D plan request.'},400)}
 const prompt=String(body?.prompt||'').trim();
 if(!prompt||prompt.length>1600)return responseJSON({error:'Describe an asset in 1–1,600 characters.'},400);
 const kind=['vehicle','building','garage','tree','character','prop'].includes(body?.kind)?body.kind:'prop';
 const system='You design a simplified, original 3D game asset using ONLY primitive meshes. Return ONLY valid JSON with this schema: {"parts":[{"name":"Part name","shape":"box","material":"paint","translation":[0,1,0],"scale":[1,1,1]}]}. Shape must be box, cylinder or sphere. Materials must be one of paint, trim, glass, highlight, light, tire, concrete, wood, foliage, skin. Coordinates in meters, Y is up, forward direction is -Z. Every dimension scale must be positive. List 6 to 45 meaningful parts to describe a coherent '+kind+'; e.g. vehicle body, cabin, wheels, windows. Avoid copyrighted logos, unsafe or explicit content, elaborate text or any code. IMPORTANT: no markdown and no additional keys.';
 try{
  const result=await verifiedProResponse(env,{model:'pro',preferences:{length:'extended',reasoning:'quick',creativity:'balanced'}},[
   {role:'system',content:system},
   {role:'user',content:'Design a stylized starter 3D asset for: '+prompt}
  ],false);
  const obj=cleanBuildOutput(result.content);
  const materials=new Set(['paint','trim','glass','highlight','light','tire','concrete','wood','foliage','skin']);
  const cleaned=[];
  for(const p of (Array.isArray(obj?.parts)?obj.parts:[]).slice(0,65)){
   if(!p||!['box','cylinder','sphere'].includes(p.shape)||!materials.has(p.material))continue;
   const t=p.translation,scale=p.scale;
   if(!Array.isArray(t)||!Array.isArray(scale)||t.length!==3||scale.length!==3)continue;
   const vals=[...t,...scale].map(Number);
   if(vals.some(v=>!Number.isFinite(v)||Math.abs(v)>80)||vals.slice(3).some(v=>v<.025))continue;
   cleaned.push({name:String(p.name||p.shape).slice(0,65),shape:p.shape,material:p.material,
     translation:vals.slice(0,3),scale:vals.slice(3,6)});
  }
  if(cleaned.length<3)return responseJSON({error:'AI could not produce a usable 3D part layout. Try a simpler description.'},422);
  return responseJSON({parts:cleaned,model:result.label,notes:'Approximate, AI-arranged primitive geometry. Review in Blender.'});
 }catch(error){
  if(isQuotaProblem(error))return responseJSON({error:'Cloudflare AI quota reached. Switch off AI planning to generate an offline GLB instead.'},429);
  console.error('NOVA model planning failed',{code:aiErrorCode(error)||'unknown'});
  return responseJSON({error:'Custom AI geometry planning is unavailable. Use standard offline GLB mode instead.'},502);
 }
}
